for status,color in zip(statuses,colors):
 vals=[r[status] for r in rows];ax.bar([r['group'].replace(' & ',' &\n') for r in rows],vals,bottom=bottom,label=status.replace('_',' ').title(),color=color);bottom=[a+b for a,b in zip(bottom,vals)]
